	v_TexCoord.xy = a_TexCoord;

	v_NormalCoord.xy = a_TexCoord * vec2(1, 0.3) * 0.7;
	v_NormalCoord.x -= g_Time * g_WaveSpeed;

	v_NormalCoord.zw = a_TexCoord * vec2(1, 0.7) * 0.3;
	v_NormalCoord.z -= g_Time * g_WaveSpeed * 0.5;
